"""Build Second Thessalonians from reviewed Scripture and original context."""
import json,copy,sys
from book_common import ROOT,OUT,scripture,source,person,finish
DATE='2026-10-07';slug='2-thessalonians';t=scripture(slug,'2TH',3)
